class Solution:
    def splitListToParts(self, head: Optional[ListNode], k: int) -> List[Optional[ListNode]]:
        curr = head
        length = 0
        while curr:
            length += 1
            curr = curr.next

        width, rem = divmod(length, k)
        ans = []
        curr = head
        for i in range(k):
            part_head = curr
            part_size = width + (1 if i < rem else 0)
            for _ in range(part_size - 1):
                if curr:
                    curr = curr.next
            if curr:
                nxt = curr.next
                curr.next = None
                curr = nxt
            ans.append(part_head)
        return ans

